-- Insert Quiz Questions for Lesson: Connect the starting point

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 17 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 17 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'connect-starting-point' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson connect-starting-point not found in module 17';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What trigger starts the follow-up workflow?', 
    '["Contact Created","Form Submitted","Email Opened","Appointment Booked"]'::jsonb,
    'Form Submitted',
    'The workflow starts with the Form Submitted trigger, filtered to only the intended enquiry form. This ensures the right form submissions begin the follow-up sequence.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you filter the Form Submitted trigger by a specific form?', 
    '["To make the workflow run faster","So unrelated forms do not trigger the sales sequence","To reduce the number of workflow executions","Because HighLevel requires it"]'::jsonb,
    'So unrelated forms do not trigger the sales sequence',
    'Without filtering by form, any form submission — including customer service forms or feedback surveys — could trigger your sales follow-up sequence. The filter ensures only the intended enquiry form starts the workflow.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you publish the workflow?', 
    '["Immediately after creating it","Only after successful end-to-end testing","After adding the first email action","When the client asks for it"]'::jsonb,
    'Only after successful end-to-end testing',
    'Keep the workflow unpublished until you have tested it thoroughly. Publishing before testing risks sending incorrect or incomplete follow-ups to real prospects.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


